package com.greenocean.backend;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import com.greenocean.backend.community.service.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseM3PrivacySurfaceTest extends PhaseLFixtures {
 @Autowired GroupMemberships memberships;
 UUID group(Member owner,Member viewer,String privacy){UUID g=UUID.randomUUID();db.update("INSERT INTO communities(id,name,slug,privacy_type,created_by) VALUES(?,?,?,?,?)",g,"Synthetic privacy "+g,"g-"+g,privacy,owner.id());db.update("INSERT INTO community_members(community_id,user_id,role,rules_version_ack) VALUES(?,?,'OWNER',1),(?,?,'MEMBER',1)",g,owner.id(),g,viewer.id());return g;}
 String groupPost(Member owner,UUID g,boolean anonymous,String body)throws Exception{var p=payload(body,anonymous);p.put("communityId",g.toString());p.put("visibility","COMMUNITY");return submit("/api/v1/posts",owner,p,201).path("id").asText();}
 @Test @Tag("malicious") void hiddenStoriesNeverEnterGlobalDiscoverySearchOrDirectoryEvenForMembers()throws Exception{var owner=member();var viewer=member();UUID g=group(owner,viewer,"HIDDEN");String post=groupPost(owner,g,true,"Synthetic hidden surface narrative");for(Member actor:List.of(owner,viewer)){assertThat(read("/api/v1/communities?q=Synthetic",actor).toString()).doesNotContain(g.toString());assertThat(read("/api/v1/posts/discovery?mode=DISCOVER",actor).toString()).doesNotContain(post);assertThat(read("/api/v1/posts/discovery?mode=FOLLOWING",actor).toString()).doesNotContain(post);assertThat(read("/api/v1/posts/feed",actor).toString()).doesNotContain(post);assertThat(read("/api/v1/search/posts?q=Synthetic",actor).toString()).doesNotContain(post);read("/api/v1/posts/"+post,actor);}mvc.perform(put("/api/v1/posts/"+post+"/bookmark").header("Authorization","Bearer "+viewer.token())).andExpect(status().isNoContent());assertThat(read("/api/v1/posts/discovery?mode=SAVED",viewer).toString()).contains(post);}
 @Test @Tag("malicious") void publicProfilesAndCountsDoNotAdvertiseNamedGroupParticipation()throws Exception{var owner=member();var viewer=member();UUID g=group(owner,viewer,"PUBLIC");String post=groupPost(owner,g,false,"Synthetic named group participation");db.update("UPDATE profiles SET is_profile_private=FALSE WHERE user_id=?",owner.id());entities.clear();String username=db.queryForObject("SELECT username FROM profiles WHERE user_id=?",String.class,owner.id());var direct=read("/api/v1/posts/"+post,viewer);assertThat(direct.path("author").path("userId").asText()).isEqualTo(owner.id().toString());assertThat(direct.toString()).doesNotContain(owner.email());assertThat(read("/api/v1/profiles/"+username+"/posts",viewer).toString()).doesNotContain(post,g.toString());var profile=read("/api/v1/profiles/"+username,viewer);assertThat(profile.toString()).doesNotContain(g.toString(),"membershipRole","community_members");assertThat(profile.path("postCount").asLong()).isZero();}
 @Test @Tag("malicious") void anonymousGroupReplyNotificationNeverIdentifiesItsAuthor()throws Exception{var owner=member();var viewer=member();UUID g=group(owner,viewer,"HIDDEN");String post=groupPost(owner,g,true,"Synthetic notification parent");submit("/api/v1/posts/"+post+"/comments",viewer,Map.of("body","Synthetic private anonymous reply","anonymous",true),201);String serialized=read("/api/v1/notifications",owner).toString();assertThat(serialized).doesNotContain(viewer.id().toString(),viewer.email(),"Synthetic private anonymous reply","Synthetic privacy");assertThat(db.queryForObject("SELECT count(*) FROM notifications WHERE user_id=? AND comment_id IS NOT NULL",Integer.class,owner.id())).isPositive();}
 @Test @Tag("malicious") void blockAndGroupSuspensionOverrideMembershipAndPreviouslySavedAccess()throws Exception{var owner=member();var viewer=member();UUID g=group(owner,viewer,"PUBLIC");String post=groupPost(owner,g,true,"Synthetic block and suspension narrative");mvc.perform(put("/api/v1/posts/"+post+"/bookmark").header("Authorization","Bearer "+viewer.token())).andExpect(status().isNoContent());db.update("INSERT INTO blocks(blocker_id,blocked_id) VALUES(?,?)",owner.id(),viewer.id());mvc.perform(get("/api/v1/posts/"+post).header("Authorization","Bearer "+viewer.token())).andExpect(status().isNotFound());db.update("DELETE FROM blocks WHERE blocker_id=?",owner.id());db.update("UPDATE communities SET status='SUSPENDED' WHERE id=?",g);mvc.perform(get("/api/v1/posts/"+post).header("Authorization","Bearer "+viewer.token())).andExpect(status().isNotFound());assertThat(read("/api/v1/posts/discovery?mode=SAVED",viewer).toString()).doesNotContain(post);}
 @Test @Tag("malicious") void guessedHiddenAndMissingReferencesHaveTheSameNondisclosingErrorAndNoStore()throws Exception{var owner=member();var viewer=member();var outsider=member();UUID g=group(owner,viewer,"HIDDEN");String actual=mvc.perform(get("/api/v1/communities/slug/g-"+g).header("Authorization","Bearer "+outsider.token())).andExpect(status().isNotFound()).andExpect(header().string("Cache-Control","no-store")).andReturn().getResponse().getContentAsString();String missing=mvc.perform(get("/api/v1/communities/slug/g-"+UUID.randomUUID()).header("Authorization","Bearer "+outsider.token())).andExpect(status().isNotFound()).andReturn().getResponse().getContentAsString();assertThat(json.readTree(actual).path("message")).isEqualTo(json.readTree(missing).path("message"));assertThat(read("/api/v1/communities?size=1",outsider).toString()).doesNotContain(g.toString());}
}
